TEMPLATES: list[dict] = [PRISON, ZOMBIE, HAUNTED, DETECTIVE, SPACE, CHAGHER]
BY_KEY: dict[str, dict] = {t["key"]: t for t in TEMPLATES}
BY_GENRE: dict[str, dict] = {}
for _t in TEMPLATES:
    BY_GENRE.setdefault(_t["genre"], _t)


def get(key: str) -> dict | None:
    return BY_KEY.get(key)


def for_genre(genre: str) -> dict | None:
    """The ready story that fits a genre key (used when no model answered); None for `custom` / unknown genres."""
    return BY_GENRE.get(genre) if genre != "custom" else None


def plan_of(template: dict) -> dict:
    """The template as a planner answer ({title, posts}) that `services.apply_plan` accepts."""
    return {"title": template["title_fa"], "posts": copy.deepcopy(template["posts"])}


def listing() -> list[dict]:
    """Gallery rows for the UI: no post texts, just what a card shows."""
    out = []
    for t in TEMPLATES:
        ends: dict[str, int] = {}
        for p in t["posts"]:
            if p["ending"]:
                ends[p["ending"]] = ends.get(p["ending"], 0) + 1
        out.append({"key": t["key"], "genre": t["genre"], "title_fa": t["title_fa"], "title_en": t["title_en"], "blurb_fa": t["blurb_fa"], "blurb_en": t["blurb_en"],
                    "posts": len(t["posts"]), "endings": ends, "cast": [{"name": c["name"], "role": c["role"], "limb": c["spec"].get("limb_colour", "#1f2430")} for c in t["cast"]],
                    "language": "fa"})
    return out
